w('pw_csn',{"airline":"China Southern","power":{"checked":"22 November 2026","answer":"China Southern allows power banks of up to 100 Wh in the cabin only, never in checked baggage. Power banks of 100 to 160 Wh need China Southern's approval, with at most 2 per passenger, and anything above 160 Wh or with no readable rating is prohibited.","sections":[{"h":"🔋 What China Southern says about power banks","p":"From the China Southern General Conditions of Carriage for Passenger and Baggage, section 4.5.4.4 \"Restrictions on Power Banks\", read on 22 November 2026.","table":{"head":["Question","China Southern rule"],"rows":[["Use","Personal use only"],["Up to 100 Wh","Allowed in the cabin"],["Above 100 Wh up to 160 Wh","Only with approval from China Southern, no more than 2 per passenger"],["Above 160 Wh","Strictly prohibited"],["No readable rated energy","Strictly prohibited (also if the energy cannot be worked out from the marked values)"],["Checked baggage","Forbidden"],["Overhead locker","Not allowed in cabin baggage loaded in the overhead storage locker"],["Where to keep it","In the seat back pocket, or under the seat in front, or where the crew designates"],["On board","Kept turned off at all times; no charging devices from it and no charging the power bank itself; a bank with a switch stays off"]]},"list":["<strong>Not on the page:</strong> a rule for a maximum number of power banks up to 100 Wh is not stated in this section."]}],"faq":[["Can I put a power bank in my checked bag on China Southern?","No. Power banks are forbidden in checked baggage and must stay with you in the cabin."],["Can I use my power bank on a China Southern flight?","No. It must stay turned off, and you may not use it to charge a device or charge the power bank itself."],["What size power bank is allowed on China Southern?","Up to 100 Wh in the cabin; 100 to 160 Wh only with approval and no more than 2; above 160 Wh is prohibited."]],"sources":[["https://www.csair.com/cts-products/cts/fastdfs/20260626/3edae764dd49418582ef740225391b1a.pdf","China Southern &mdash; General Conditions of Carriage for Passenger &amp; Baggage"]]}})
w('pw_cea',{"airline":"China Eastern","power":{"checked":"22 November 2026","answer":"China Eastern allows each passenger no more than two power banks, carried in the cabin and never in the overhead compartment. A power bank must stay off for the whole flight and may not charge a device or be charged on board.","sections":[{"h":"🔋 What China Eastern says about power banks","p":"From the China Eastern General Conditions for Transportation of Passengers and Baggage (July 2026), sections 5.4.2.4 and 7.2.1.3, read on 22 November 2026.","table":{"head":["Question","China Eastern rule"],"rows":[["How many","No more than two power banks per passenger"],["Overhead compartment","Power banks must not be stored there"],["Checked baggage","Power banks are listed as items for carry-on only, not checked baggage"],["On board, from boarding until everyone has left","No using it to charge devices and no charging the power bank itself"],["State","Power banks must be kept off at all times on board"]]},"list":["<strong>Not on the page:</strong> the sections read give no Wh limit for power banks; the spare battery rule in the same document is one battery of 300 Wh or two of 160 Wh, for mobility aids."]}],"faq":[["How many power banks can I take on China Eastern?","No more than two per passenger."],["Can I use a power bank on China Eastern?","No. Charging devices from it or charging the power bank itself is not allowed from boarding until all passengers have left the aircraft, and it must stay off."]],"sources":[["https://www.ceair.com/global/en_static/Announcement/TravelTips/dsGeneralCondition/chinaEasternLuggageRules/domesticRules/202201/W020260724485859129374.pdf","China Eastern &mdash; General Conditions for Transportation of Passengers and Baggage (July 2026)"]]}})
w('pw_fd',{"airline":"flydubai","power":{"checked":"22 November 2026","answer":"flydubai allows one power bank per passenger, of 100 Wh or less with the rating clearly marked. It must be in hand baggage only, switched off, protected from short circuits, never in an overhead locker, never in checked baggage, and not used on board.","sections":[{"h":"🔋 What flydubai says about power banks","p":"From the flydubai Dangerous goods page, section \"Power banks\", read on 22 November 2026.","table":{"head":["Question","flydubai rule"],"rows":[["How many","Only one power bank per passenger"],["Capacity","100 Wh or less, clearly marked (labelled, embossed or printed) on the device; over 100 Wh strictly prohibited"],["Which devices count","Any power bank, portable charger, battery pack, pocket charger or power station whose main job is portable power"],["State","Switched off and protected from short circuits and accidental activation; original retail packaging or a pouch is advisable"],["On board","Use is strictly prohibited, including charging devices or the power bank from aircraft sockets"],["Where","In hand baggage under the seat or in the seat pocket; not in overhead lockers"],["Hand baggage","Yes"],["Checked baggage","No"],["Breaking the rules","Can lead to denial of carriage"],["Flights to and from India","The MOBIKINS MK-PB-04 power bank is prohibited in hand baggage, checked baggage and cargo"]]},"list":["<strong>Not on the page:</strong> the same page separately allows up to 20 spare lithium batteries per passenger in hand baggage, but says power banks follow the power bank section."]}],"faq":[["How many power banks can I take on flydubai?","Only one per passenger, of 100 Wh or less, in hand baggage."],["Can I charge my phone from a power bank on flydubai?","No. Using a power bank on board is strictly prohibited, including charging devices or charging the power bank from aircraft sockets."]],"sources":[["https://www.flydubai.com/en/flying-with-us/baggage/dangerous-goods/","flydubai &mdash; Dangerous goods: restricted and prohibited items"]]}})
raw=open(D+'ladder_log.json','rb').read().decode('utf8');crlf='\r\n' in raw
