for s,o in [('china-southern','csair.com Conditions of Carriage 4.5.4.4'),('china-eastern','ceair.com Conditions July 2026 5.4.2.4 / 7.2.1.3'),('flydubai','flydubai.com Dangerous goods Power banks section')]:
    k='airline/%s/power-bank'%s
